import {buildPlayableMatch} from './playable-match.js';
import {buildMatchdayCrowd} from './matchday-crowd.js';
import {buildEntrancePlayers} from './entrance-players.js';
import {createMatchdayAudio} from './matchday-audio.js';
import {entranceSample,ENTRANCE_DURATION} from './matchday-route.js';
import {buildMatchdaySet} from './matchday-set.js';
import {homeXI,awayXI,substitutes} from './matchday-roster.js';
import {buildMatchSetup} from './football-setup.js';

export function buildMatchdayExperience({scene,stadium,onBegin,onPose,onFinish,onExit,onPause,onPrepare,onVisitBench,onGameCamera,onGameView,toast,reducedMotion=false,mobile=false}){
 const $=id=>document.getElementById(id),dialog=$('match-dialog'),panel=$('match-controls'),crowd=buildMatchdayCrowd(stadium.bowl,stadium.seatPositions,{mobile,reducedMotion}),players=buildEntrancePlayers(scene,{mobile});
 let active=false,cinematic=false,paused=false,pending=false,time=0,playerSeconds=0,worldTime=0,uiClock=0,visualClock=0,redraw=false,token=0,lastCountdown=-1,roared=false,steps=0,stepDistance=0,lastPosition=null;
 const setting=buildMatchdaySet(stadium.bowl,stadium.matchBall);
 let storage;try{storage=globalThis.localStorage;}catch{}const setup=buildMatchSetup(storage);
 let lastYaw=0,rosterWasPaused=false;
 for(const[team,title,xi]of [['home','FC BAYERN',homeXI],['away','DORTMUND',awayXI]]){const section=document.createElement('section'),heading=document.createElement('h3');heading.textContent=title;section.append(heading);for(const player of [...xi,...substitutes.filter(p=>p.team===team)]){const row=document.createElement('div'),number=document.createElement('b'),name=document.createElement('span');row.className='roster-player';number.textContent=player.player.number;name.textContent=player.player.name+(player.keeper?' · GK':'')+(player.role==='substitute'?' · 替补':'');row.append(number,name);section.append(row);}$('match-roster-content').append(section);}
 const audio=createMatchdayAudio({onState:state=>{document.body.dataset.matchSound=state.state;$('match-volume').value=String(Math.round(state.volume*100));$('match-mute').setAttribute('aria-pressed',String(state.muted));$('match-mute').setAttribute('aria-label',state.state==='unavailable'?'重试加载看台声':state.muted?'开启看台声':'静音看台声');const labels={loading:'声浪加载中',unavailable:'声音未加载 · 点击重试',playing:'看台声浪',muted:'已静音',paused:'声音已暂停',off:'声音已关闭'};$('match-audio-status').textContent=labels[state.state]||'看台声浪';}});
 const game=buildPlayableMatch({scene,stadium,players,audio,mobile,onCamera:onGameCamera,onView:onGameView,onPause:setPaused,onRestart:()=>start(false,true),onExit:exit,onChangeMatch:()=>{exit();launch();}});
 function renderUI(){const sample=entranceSample(time,{reducedMotion}),state=!active?'off':pending?'loading':paused?'paused':game.active?game.state.phase:cinematic?sample.phase:'free';document.body.dataset.matchday=state;document.body.dataset.matchProgress=(time/ENTRANCE_DURATION).toFixed(3);document.body.dataset.matchCrowd=active?String(crowd.count):'0';document.body.dataset.matchAudioSeconds=audio.duration.toFixed(2);document.body.dataset.matchPlayers=active?players.positions:'';document.body.classList.toggle('match-cinematic',active&&cinematic);document.body.classList.toggle('match-free',active&&!cinematic);document.body.classList.toggle('match-paused',paused);
  $('match-status').textContent=pending?'正在准备入场体验':paused?'体验已暂停':cinematic?sample.label:'比赛日 · 自由漫游';$('match-pause').textContent=paused?'继续':'暂停';$('match-pause').setAttribute('aria-label',paused?'继续入场体验':'暂停入场体验');$('match-pause').hidden=!cinematic&&!paused;$('match-skip').textContent=cinematic?'结束跟随':'跟队入场';$('match-skip').setAttribute('aria-label',cinematic?'结束跟随，留在当前位置':'选择跟队入场');$('match-cheer').hidden=cinematic;$('match-progress-fill').style.width=(time/ENTRANCE_DURATION*100)+'%';$('match-countdown').hidden=!active||!cinematic||pending||paused||!sample.countdown;$('match-countdown').textContent=String(sample.countdown||'');$('match-level').value=audio.level;
 }
 function launch(){setup.refresh();dialog.showModal();}
 async function start(automatic=false,play=false){const id=++token;if(game.active)game.exit();active=true;cinematic=automatic;paused=false;pending=true;time=automatic?0:ENTRANCE_DURATION;playerSeconds=automatic?0:200;lastCountdown=-1;roared=false;stepDistance=0;lastPosition=null;panel.hidden=false;document.body.classList.add('match-active');crowd.setEnabled(true);setting.setEnabled(true);stadium.setMatchday?.(true);players.root.visible=false;players.reset();
  // start() resumes the AudioContext in this click event before any network await.
  const options=setup.options,sound=audio.start(),models=players.prepare().then(async()=>{if(!active||id!==token)return;players.setOpponent(play?options.opponent:'dortmund');await onPrepare?.(players.root);if(play)await onPrepare?.(game.root);});dialog.close();onBegin?.({cinematic:automatic,playing:play});if(play)game.start(options);if(automatic)onPose?.(entranceSample(0,{reducedMotion}),{instant:true});renderUI();const [soundResult,modelResult]=await Promise.allSettled([sound,models]);if(!active||id!==token)return;pending=false;if(soundResult.status==='rejected'||!soundResult.value)toast?.('声景暂未加载，可点击声音按钮重试；画面仍可继续体验。');if(modelResult.status==='rejected'){toast?.('球员模型未加载，请检查网络后重试。');if(play)game.fail();}else if(play)game.ready();renderUI();
 }
 function finish(){if(!active||game.active)return;time=ENTRANCE_DURATION;playerSeconds=Math.max(playerSeconds,ENTRANCE_DURATION);cinematic=false;paused=false;onPose?.(entranceSample(time,{reducedMotion}),{instant:true});audio.setPaused(false);if(!roared){roared=true;audio.cheer();}onFinish?.();renderUI();}
 function setPaused(value){if(!active)return;paused=value;audio.setPaused(value);if(game.active)game.setPaused(value);onPause?.(value);renderUI();}
 function stopFollowing(){if(!cinematic)return;cinematic=false;paused=false;audio.setPaused(false);onFinish?.({manual:true});renderUI();}
 function exit(){if(!active){dialog.close();return;}token++;game.exit();active=false;cinematic=false;paused=false;pending=false;audio.stop();crowd.setEnabled(false);setting.setEnabled(false);stadium.setMatchday?.(false);players.root.visible=false;panel.hidden=true;$('match-countdown').hidden=true;document.body.classList.remove('match-active','match-cinematic','match-free','match-paused');onExit?.();renderUI();}
 function update(dt,position,yaw,input={}){redraw=false;if(!active)return;if(game.active){if(!paused){worldTime+=Math.min(dt,.25);crowd.update(worldTime);audio.update(position,yaw,dt);visualClock+=dt;if(visualClock>1/24){visualClock=0;redraw=true;}}game.update(dt,{...input,yaw:input.yaw??yaw},position);document.body.dataset.matchBall=stadium.matchBall?.position.toArray().map(v=>v.toFixed(3)).join(',')||'';uiClock+=dt;if(uiClock>.1){uiClock=0;renderUI();}return;}if(!paused){worldTime+=Math.min(dt,.25);if(!pending)playerSeconds+=Math.min(dt,.25);visualClock+=dt;if(visualClock>1/24){visualClock=0;redraw=true;}if(cinematic&&!pending){time=Math.min(ENTRANCE_DURATION,time+Math.min(dt,.25));const sample=entranceSample(time,{reducedMotion});onPose?.(sample,{dt});if(sample.countdown!==lastCountdown){lastCountdown=sample.countdown;audio.cue(sample.countdown);}if(sample.reveal>.57&&!roared){roared=true;audio.cheer();}if(sample.finished)finish();}
   setting.update(dt);crowd.update(worldTime);const p=cinematic?entranceSample(time,{reducedMotion}):null,walked=lastPosition?Math.hypot(position.x-lastPosition.x,position.z-lastPosition.z):0,moving=p?p.moving:walked>.003;
   if(walked<2&&moving)stepDistance+=walked;if(stepDistance>.79){stepDistance%=.79;audio.footstep(steps++);}lastPosition={x:position.x,y:position.y,z:position.z};lastYaw=yaw;$('match-kick').hidden=cinematic||!setting.nearBall(position);players.update(playerSeconds,worldTime,position);const inTunnel=position.x>-72.8&&position.x<-40.4&&Math.abs(position.z)<2.5&&position.y<4;players.root.visible=players.ready&&!pending&&(inTunnel||stadium.root.visible&&stadium.bowl.visible)&&Math.hypot(position.x,position.z)<110&&position.y<10;audio.update(position,yaw,dt);
  }
  document.body.dataset.matchBall=stadium.matchBall?.position.toArray().map(v=>v.toFixed(3)).join(',')||'';uiClock+=dt;if(uiClock>.1){uiClock=0;renderUI();}
 }
 $('matchday-launch').onclick=launch;$('match-dialog-close').onclick=()=>dialog.close();$('match-start').onclick=()=>start(true);$('match-play').onclick=()=>start(false,true);$('match-manual').onclick=()=>start(false);$('match-pause').onclick=()=>setPaused(!paused);$('match-skip').onclick=()=>cinematic?stopFollowing():launch();$('match-cheer').onclick=()=>audio.cheer();$('match-exit').onclick=exit;$('match-volume').oninput=e=>audio.setVolume(Number(e.target.value)/100);$('match-mute').onclick=()=>{if(audio.state==='unavailable')audio.start().then(()=>{if(paused)audio.setPaused(true);});else audio.setMuted(!audio.muted);};
 $('match-more').onclick=()=>{const expanded=panel.classList.toggle('expanded');$('match-more').setAttribute('aria-expanded',String(expanded));};$('match-lineups').onclick=()=>{rosterWasPaused=paused;setPaused(true);$('match-roster-dialog').showModal();};$('match-roster-dialog').addEventListener('close',()=>{if(!rosterWasPaused)setPaused(false);});$('match-roster-close').onclick=()=>$('match-roster-dialog').close();$('match-kick').onclick=()=>{if(lastPosition)setting.kick(lastPosition,lastYaw);};
 $('match-visit-bench').onclick=()=>{$('match-roster-dialog').close();stopFollowing();onVisitBench?.();};
 return{launch,start,exit,finish,stopFollowing,update,setPaused,kick:(position,yaw)=>active&&!game.active&&setting.kick(position,yaw),gameAction:game.action,beginGameCharge:game.beginCharge,releaseGameCharge:game.releaseCharge,cycleGameCamera:game.cycleCamera,setGameView:game.setView,showGameHelp:game.showHelp,restartGame:()=>start(false,true),get playing(){return active&&game.active;},get gameView(){return game.view;},get gameCamera(){return game.camera;},get gameState(){return game.state;},get active(){return active;},get cinematic(){return active&&cinematic;},get paused(){return paused;},isAnimating:()=>active&&!paused&&(game.active||cinematic&&!pending||setting.isAnimating()||redraw&&(players.root.visible||stadium.root.visible&&stadium.bowl.visible))};
}
